   {draft.session_type==='follow_up'&&<VisitPart anchor="psychometrics" number="05" title="Βαθμολογίες έναντι προηγούμενης επίσκεψης">{contextReady?<VisitScores bundle={bundle} sessionId={draft.id} reload={reloadContext}/>:<p role="status">Φόρτωση ψυχομετρικών…</p>}</VisitPart>}
   {draft.session_type==='initial_assessment'&&assessment()}
   <VisitPart anchor="medication" number="06" title={draft.session_type==='initial_assessment'?'Αγωγή':'Αγωγή & ανασκόπηση θεραπείας'}>{contextReady?<><p className="visit-hint">Αγωγή · ενημερώνει άμεσα τον φάκελο με την αποθήκευση, ακόμη και σε επίσκεψη με μη ολοκληρωμένη καταγραφή.</p><MedicationTable bundle={bundle} sessionId={draft.id} reload={reloadContext} editablePlan editableEffects firstAssessment={draft.session_type==='initial_assessment'} registerFlusher={registerFlusher} onDirtyChange={onDirtyChange}/>{draft.session_type==='initial_assessment'?<>{['adherence','effects'].filter(key=>sections.find(s=>s.section_key===key)?.content.trim()).map(key=><details key={key} className="visit-additional"><summary>{key==='adherence'?'Προϋπάρχουσα λήψη αγωγής':'Προϋπάρχουσα ανοχή / παρενέργειες'}</summary><p style={{whiteSpace:'pre-wrap'}}>{sections.find(s=>s.section_key===key)?.content}</p></details>)}</>:<div className="visit-related-fields" data-visit-part="adherence">{editor('adherence','Λήψη αγωγής')}{editor('effects','Συνολική ανοχή / παρενέργειες')}</div>}</>:<p role="status">Φόρτωση αγωγής…</p>}</VisitPart>
   {draft.session_type==='follow_up'&&assessment()}
   <VisitPart anchor="plan" number={draft.session_type==='follow_up'?'08':'07'} title={draft.session_type==='initial_assessment'?'Πλάνο & επανεκτίμηση':'Αποφάσεις & επόμενος έλεγχος'}>{draft.session_type==='initial_assessment'?<><SectionEditor key={draft.id+':plan'} sessionId={draft.id} definition={{key:'plan',title:'Πλάνο & επανεκτίμηση'}} placeholder="Θεραπευτικές αποφάσεις, παρεμβάσεις, επόμενα βήματα και τι θα επανεκτιμηθεί..." existing={sections.find(s=>s.section_key==='plan')} proposals={bundle.proposals.filter(p=>p.session_id===draft.id&&p.section_key==='plan')} onSaved={reload} registerFlusher={registerFlusher} onDirtyChange={onDirtyChange}/>{sections.find(s=>s.section_key==='review')?.content.trim()&&<details className="visit-additional"><summary>Προϋπάρχουσα καταγραφή επανεκτίμησης</summary><p style={{whiteSpace:'pre-wrap'}}>{sections.find(s=>s.section_key==='review')?.content}</p></details>}</>:<div className="visit-related-fields">{editor('plan','Αποφάσεις / παρεμβάσεις')}{editor('review','Τι και πότε θα επανεκτιμηθεί')}</div>}</VisitPart>
   {contextReady&&<VisitPart anchor="appointment" number="09" title="Επόμενο ραντεβού"><VisitNextAppointment bundle={bundle} reload={reloadContext} registerFlusher={registerFlusher} onDirtyChange={onDirtyChange} showHeading={false}/></VisitPart>}
   {draft.session_type==='follow_up'&&contextReady&&<details className="visit-additional"><summary>Συμπλήρωση διαχρονικού ιστορικού</summary><VisitHistory bundle={bundle} sessionId={draft.id} reload={reloadContext} registerFlusher={registerFlusher} onDirtyChange={onDirtyChange}/></details>}
   </VisitCanvas>
  </fieldset>

  <p className="visit-hint">Όλα τα κλινικά πεδία είναι προαιρετικά. Οι κλινικές σημειώσεις αποθηκεύονται χωρίς τελική καταχώριση όσο εργάζεστε. Η οριστικοποίηση κλείνει την καταγραφή και εντάσσει τις σημειώσεις στη σύνοψη του φακέλου. Οι αποθηκευμένες αλλαγές αγωγής και τα ραντεβού καταχωρίζονται άμεσα, ανεξάρτητα από την οριστικοποίηση.</p>
  {remaining.length>0&&<div className="visit-finalize-guidance" aria-label="Εκκρεμότητες ολοκλήρωσης"><strong>Πριν την ολοκλήρωση</strong><ul>{remaining.map((item,index)=><li key={item.anchor+index}><button type="button" onClick={()=>goToPart(item.anchor)}>{item.message}</button></li>)}</ul></div>}
  <p className="visit-hint">«Συνέχεια αργότερα»: αποθήκευση χωρίς τελική καταχώριση και προσθήκη στις εκκρεμότητες. Η επίσκεψη δεν οριστικοποιείται.</p>
  <div className="finalize-bar">
   <button onClick={()=>void finalizeSafely()} aria-describedby={showFinalizeGuidance&&blocker?'visit-finalize-guidance':undefined} disabled={finalizing||flushing||finishingLater}><Check size={16}/>{flushing&&dirtyCount>0?'Αποθήκευση αλλαγών…':finalizing?'Καταχώριση…':'Καταχώριση επίσκεψης'}</button>{onFinishLater&&<button type="button" className="finalize-later" disabled={finalizing||flushing||finishingLater} onClick={()=>void finishLater()}>{finishingLater?'Αποθήκευση σημειώσεων…':'Συνέχεια αργότερα'}</button>}
   {showFinalizeGuidance&&blocker&&<span id="visit-finalize-guidance" className="visit-finalize-guidance" role="status">{blocker.message} <button type="button" onClick={()=>goToPart(blocker.anchor)}>Μετάβαση</button></span>}
  </div>

  {flushError&&<div className="save-state error" role="alert"><strong>Υπάρχουν μη αποθηκευμένες αλλαγές.</strong> {flushError} <span>Διορθώστε το πρόβλημα ή δοκιμάστε ξανά πριν οριστικοποιήσετε.</span></div>}
  {refreshError&&<div className="save-state" role="status">{refreshError}</div>}
  {finalizeError&&<div className="save-state error" role="alert">{finalizeError}</div>}

  </fieldset>
  {completed.length>0&&<div className="previous-visits"><span className="kicker">ΠΡΟΗΓΟΥΜΕΝΕΣ</span><CompletedList sessions={completed} onSelect={id=>void flushAll().then(()=>onSelectSession(id)).catch(()=>{})}/></div>}
 </section>);
}

function FollowupFinalizationGuard({guard}:{guard:MutableRefObject<((fresh:PatientBundle)=>void)|null>}){
 const {checkConsistency}=useFollowupDraft();
 useEffect(()=>{guard.current=checkConsistency;return()=>{if(guard.current===checkConsistency)guard.current=null}},[guard,checkConsistency]);
 return null;
}

function CompletedList({sessions,onSelect}:{sessions:DemoSession[];onSelect:(id:string)=>void}){
 return <div className="completed-session-list">{sessions.map(session=><button className="completed-session-row" key={session.id} onClick={()=>onSelect(session.id)}><CheckCircle2 size={18}/><div><strong>{session.session_type==='initial_assessment'?'Αρχική αξιολόγηση':'Επαναληπτική συνεδρία'}</strong><span>Οριστικοποιήθηκε {fmt(session.completed_at)}</span></div><span className="open-session-label">Άνοιγμα</span></button>)}</div>;
}

function CompletedSessionView({session,bundle,onBack,reload,registerFlusher,onDirtyChange}:{session:DemoSession;bundle:PatientBundle;onBack:()=>void;reload:()=>Promise<unknown>;registerFlusher:RegisterFlusher;onDirtyChange:DirtyChange}){
 return <>{session.continuity?.approved_at&&<section className="visit-part"><header><h3><PatientVisualIcon name="summary"/>Επιβεβαιωμένη κλινική μνήμη</h3></header><p style={{whiteSpace:'pre-wrap'}}>{session.continuity.clinical_state_summary}</p><p><strong>Απόφαση θεραπείας:</strong> {session.continuity.treatment_decision}</p><p><strong>Επόμενος έλεγχος:</strong> {session.continuity.next_review_focus}</p><p><strong>Λήψη αγωγής:</strong> {session.continuity.adherence}</p>{session.continuity.pinned_context&&<p>📌 {session.continuity.pinned_context}</p>}<p className="visit-hint">Επιβεβαιώθηκε {fmt(session.continuity.approved_at)} · {session.continuity.source==='ai_assisted'?'Πρόταση AI ελεγμένη από τον κλινικό':'Χειροκίνητη καταγραφή'}</p><details><summary>Αρχικό κείμενο κλινικού</summary><p style={{whiteSpace:'pre-wrap'}}>{session.continuity.transcript||'Δεν χρησιμοποιήθηκε ξεχωριστή αρχική καταγραφή.'}</p></details></section>}<CustomVisitSectionsRead bundle={bundle} sessionId={session.id}/><CompletedRecordEditor key={session.id} session={session} bundle={bundle} reload={reload} onBack={onBack} registerFlusher={registerFlusher} onDirtyChange={onDirtyChange}/></>;
}

function VisitPart({number:_,title,children,anchor}:{number:string;title:string;children:React.ReactNode;anchor?:string}){
 // Single-field interview and structured MSE already own their content surface.
 const ownsSurface=anchor==='interview'||anchor==='mse';
 return <section className="visit-part" data-visit-part={anchor}>
  {anchor!=='interview'&&<header><h3><PatientVisualIcon name={anchor}/>{title}</h3></header>}
  <div className={ownsSurface?'visit-part-content':'visit-part-surface'}>{children}</div>
 </section>;
}

components/patients/CompletedRecordEdito:
'use client';
import PatientVisualIcon from './PatientVisualIcon';
import {useEffect,useMemo,useRef,useState} from 'react';
import {X,Check} from 'lucide-react';
import type {DemoRisk,DemoSession,PatientBundle} from '@/lib/patients/demo-runtime';
import type {VisitDocument,DocumentField} from '@/lib/clinical/visit-document';
import {initialDocument,mseItems} from '@/lib/clinical/visit-document';
import {effectiveDocument,effectiveRisk,effectiveText,correctionsFor} from '@/lib/clinical/corrections';
import {demoPost} from '@/lib/patients/demo-client';
import {formatClinicDateTime} from '@/lib/clinic-time';
import RiskAssessmentRead from './RiskAssessmentRead';
import {riskTreePath,riskTreeQuestions} from '@/lib/clinical/risk-tree';
import MseDomain from './MseDomain';
import ICD10Picker from './ICD10Picker';

const narrativeKeys=['interview','adherence','effects','functioning','plan','review'] as const;
const assessmentLabels:Record<string,string>={diagnosis:'Διάγνωση',formulation:'Διατύπωση περίπτωσης',impression:'Κλινική εκτίμηση'};
const riskOptions=[['not_assessed','Δεν διερευνήθηκε'],['unknown','Άγνωστο'],['negative','Αρνητικό'],['positive','Θετικό']] as const;
function riskShape(r?:DemoRisk){return {suicidal_ideation:r?.suicidal_ideation||'not_assessed',intent:r?.intent||'not_assessed',plan:r?.plan||'not_assessed',self_harm:r?.self_harm||'not_assessed',attempt_history:r?.attempt_history||'not_assessed',harm_to_others:r?.harm_to_others||'not_assessed',protective_factors:r?.protective_factors||'',clinical_note:r?.clinical_note||'',tree:r?.tree};}
const same=(a:unknown,b:unknown)=>JSON.stringify(a)===JSON.stringify(b);

export default function CompletedRecordEditor({session,bundle,reload,onBack,registerFlusher,onDirtyChange}:{session:DemoSession;bundle:PatientBundle;reload:()=>Promise<unknown>;onBack:()=>void;registerFlusher:(key:string,flush:()=>Promise<void>)=>(()=>void);onDirtyChange:(key:string,dirty:boolean)=>void}){
 const corrections=bundle.corrections||[];
 const sections=bundle.sections.filter(section=>section.session_id===session.id);
 const find=(key:string)=>sections.find(section=>section.section_key===key);
 const effectiveMse=effectiveDocument(find('mse'),corrections,session.id,'mse');
 const effectiveAssessment=effectiveDocument(find('assessment'),corrections,session.id,'assessment');
 const baseMse=useMemo(()=>initialDocument('mse',effectiveText(find('mse'),corrections,session.id,'mse'),effectiveMse),[bundle,session.id]);
 const baseAssessment=useMemo(()=>initialDocument('assessment',effectiveText(find('assessment'),corrections,session.id,'assessment'),effectiveAssessment),[bundle,session.id]);
 const baseRisk=useMemo(()=>riskShape(effectiveRisk(bundle.risks.find(item=>item.session_id===session.id),corrections,session.id)),[bundle,session.id]);
 const baseNarrative=useMemo(()=>Object.fromEntries(narrativeKeys.map(key=>[key,effectiveText(find(key),corrections,session.id,key)])) as Record<(typeof narrativeKeys)[number],string>,[bundle,session.id]);

 const [editing,setEditing]=useState(false),[reason,setReason]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const correctionRequest=useRef<string|null>(null);
 const [editedMse,setMse]=useState<VisitDocument>(baseMse),[editedAssessment,setAssessment]=useState<VisitDocument>(baseAssessment),[editedRisk,setRisk]=useState(baseRisk),[editedNarrative,setNarrative]=useState(baseNarrative);
 const baseline=useRef({mse:baseMse,assessment:baseAssessment,risk:baseRisk,narrative:baseNarrative,count:0});
 // Viewing always follows canonical data. Editing starts from one frozen version.
 const mse=editing?editedMse:baseMse,assessment=editing?editedAssessment:baseAssessment,risk=editing?editedRisk:baseRisk,narrative=editing?editedNarrative:baseNarrative;
 const ready=session.status==='completed'&&session.patient_id===bundle.patient.id;
 function beginEditing(){
  if(!ready)return;
  baseline.current={mse:baseMse,assessment:baseAssessment,risk:baseRisk,narrative:baseNarrative,count:correctionsFor(corrections,session.id).length};
  setMse(baseMse);setAssessment(baseAssessment);setRisk(baseRisk);setNarrative(baseNarrative);setReason('');setError('');correctionRequest.current=crypto.randomUUID();setEditing(true);
 }

 function reset(){setMse(baseMse);setAssessment(baseAssessment);setRisk(baseRisk);setNarrative(baseNarrative);setReason('');setError('');setEditing(false);correctionRequest.current=null}
 function changeMse(index:number,text:string){setMse(current=>({...current,fields:current.fields.map((field,i)=>i===index?{...field,text,review:text.trim()?'changed':'not_assessed'}:field)}))}
 function changeAssessment(index:number,change:Partial<DocumentField>){setAssessment(current=>({...current,fields:current.fields.map((field,i)=>i===index?{...field,...change}:field)}))}
 function changeRisk(key:'suicidal_ideation'|'intent'|'plan'|'self_harm'|'attempt_history'|'harm_to_others',value:string){
  setRisk(current=>{
   const answerKey:keyof NonNullable<typeof current.tree>['answers']|null=key==='suicidal_ideation'?'wish':key==='harm_to_others'?'others':key==='intent'?'intent':key==='plan'?'plan':null;
   return {...current,[key]:value,...(answerKey&&current.tree?{tree:{...current.tree,answers:{...current.tree.answers,[answerKey]:value}}}:{})};
  });
 }
 function makePatch(){
  const value:Record<string,{before:unknown;after:unknown}>={};
  if(!editing)return value;
  const base=baseline.current;
  for(const key of narrativeKeys)if(!same(base.narrative[key],narrative[key]))value[key]={before:base.narrative[key],after:narrative[key]};
  if(!same(base.mse,mse))value.mse={before:base.mse,after:mse};
  if(!same(base.assessment,assessment))value.assessment={before:base.assessment,after:assessment};
  if(!same(base.risk,risk))value.risk={before:base.risk,after:risk};
  return value;
 }
 const pending=Object.keys(makePatch()).length;
 const history=correctionsFor(corrections,session.id);
 const correctionDirty=editing&&(pending>0||Boolean(reason.trim()));
 const correctionKey='completed-correction:'+session.id;
 useEffect(()=>{onDirtyChange(correctionKey,correctionDirty);return()=>onDirtyChange(correctionKey,false)},[correctionKey,correctionDirty,onDirtyChange]);
 useEffect(()=>registerFlusher(correctionKey,async()=>{if(correctionDirty)throw new Error('Αποθηκεύστε ή ακυρώστε τη διόρθωση πριν φύγετε από την καταγραφή.')}),[correctionKey,correctionDirty,registerFlusher]);
 async function save(){
  if(!pending||!reason.trim()||busy)return;
  if(history.length!==baseline.current.count){setError('Η καταγραφή διορθώθηκε όσο την επεξεργαζόσασταν. Ακυρώστε τη διόρθωση και ανοίξτε την ενημερωμένη έκδοση.');return}
  setBusy(true);setError('');
  const requestId=correctionRequest.current||(correctionRequest.current=crypto.randomUUID());
  try{await demoPost({action:'correct_session',session_id:session.id,request_id:requestId,reason:reason.trim(),patch:makePatch(),expected_count:baseline.current.count});await reload();setEditing(false);setReason('');correctionRequest.current=null}
  catch(e){setError(e instanceof Error?e.message:'Δεν αποθηκεύτηκε η διόρθωση.')}
  finally{setBusy(false)}
 }
 return <section className="session-workspace completed-session-view corrected-record-view">
  <div className="session-work-head">
   <div><button className="session-back-button" onClick={()=>{if(correctionDirty){setError('Αποθηκεύστε ή ακυρώστε τη διόρθωση πριν φύγετε από την καταγραφή.');return}onBack()}}>← Συνεδρίες</button><span className="visit-label completed"><span>ΟΡΙΣΤΙΚΟΠΟΙΗΜΕΝΟ</span><i/> {session.session_type==='initial_assessment'?'ΑΡΧΙΚΗ ΑΞΙΟΛΟΓΗΣΗ':'ΕΠΑΝΕΞΕΤΑΣΗ'}</span><h2>{session.session_type==='initial_assessment'?'Αρχική αξιολόγηση':'Επανεξέταση'}</h2><p>Η αρχική καταγραφή παραμένει αμετάβλητη. Οι διορθώσεις αποθηκεύονται ξεχωριστά με ιστορικό αλλαγών.</p></div>
   <div className="completed-record-actions"><span className="draft-updated">Ολοκληρώθηκε {formatClinicDateTime(session.completed_at||session.started_at)}</span>{!editing&&<button type="button" disabled={!ready} onClick={beginEditing}>{ready?'Διόρθωση καταγραφής':'Φόρτωση καταγραφής…'}</button>}</div>
  </div>

  <fieldset disabled={!editing||busy} className="visit-document completed-record-form">
   <section className="visit-part"><header><h3><PatientVisualIcon name="notes"/>{session.session_type==='follow_up'?'Συμπτώματα / πορεία':'Λόγος προσέλευσης & παρούσα εικόνα'}</h3></header><div><textarea rows={4} value={narrative.interview} onChange={e=>setNarrative(v=>({...v,interview:e.target.value}))}/></div></section>
   {session.session_type==='follow_up'&&<section className="visit-part"><header><h3><PatientVisualIcon name="medication"/>Παρενέργειες & λήψη αγωγής</h3></header><div className="completed-correction-grid"><label>Λήψη αγωγής<textarea rows={3} value={narrative.adherence} onChange={e=>setNarrative(v=>({...v,adherence:e.target.value}))}/></label><label>Παρενέργειες<textarea rows={3} value={narrative.effects} onChange={e=>setNarrative(v=>({...v,effects:e.target.value}))}/></label></div></section>}
   <section className="visit-part"><header><h3><PatientVisualIcon name="mse"/>MSE</h3></header><div className="mse-columns">{[mseItems.slice(0,6),mseItems.slice(6)].map((items,column)=><div className="mse-column" key={column}>{items.map(([key])=>{const index=mse.fields.findIndex(field=>field.key===key);if(index<0)return null;return <MseDomain key={key} field={mse.fields[index]} onChange={text=>changeMse(index,text)} onBlur={()=>{}}/>})}</div>)}</div>{mse.fields.map((field,index)=>field.key==='legacy'?<MseDomain key="legacy" field={field} onChange={text=>changeMse(index,text)} onBlur={()=>{}}/>:null)}</section>
