function CustomVisitSection(p:Shared&{sectionKey:string;title:string;existing?:DemoSection}){
 const base=p.existing?readCustomSection(p.existing.content):{title:p.title,body:''};
 const key='section:'+p.sectionKey;
 const draft=useClinicalDraft({storageKey:p.session.id+':'+key,initial:base.body,version:p.existing?.version??null,write:async(content,version)=>{const result=await saveCustom({action:'save_custom_section',session_id:p.session.id,section_key:p.sectionKey,title:base.title,content,expected_version:version});return {value:readCustomSection(result.section.content).body,version:result.section.version}},onSaved:p.reload,onDirty:dirty=>p.onDirtyChange(key,dirty)});
 const [comparison,setComparison]=useState<DemoSection|null|undefined>();
 useEffect(()=>p.registerFlusher(key,draft.flush),[p.registerFlusher,key,draft.flush]);
 return <div className={styles.custom}><label>{base.title}<textarea rows={4} maxLength={20000} value={draft.value} placeholder="Γράψε τις σημειώσεις σου…" onChange={e=>draft.change(e.target.value)} onBlur={()=>void draft.flush().catch(()=>{})}/></label><p role="status">{draftSaveStatus({saving:draft.saving,dirty:draft.dirty,error:draft.error,savedAt:draft.savedAt,recorded:Boolean(p.existing)})}</p>{draft.error&&<><button type="button" onClick={()=>void draft.flush().catch(()=>{})}>Επανάληψη αποθήκευσης</button><button type="button" onClick={()=>void p.reload().then(b=>setComparison((b as PatientBundle).sections.find(s=>s.session_id===p.session.id&&s.section_key===p.sectionKey)||null))}>Σύγκριση με αποθηκευμένο</button></>}{comparison!==undefined&&<div className="conflict-review"><p>Το δικό σου κείμενο διατηρείται.</p><p className={styles.read}>{comparison?readCustomSection(comparison.content).body:'Κενή ενότητα'}</p><button type="button" onClick={()=>{draft.resolve(draft.currentValue(),comparison?readCustomSection(comparison.content).body:'',comparison?.version??null);setComparison(undefined)}}>Διατήρηση του δικού μου</button><button type="button" onClick={()=>{draft.acceptServerPreservingLocal(comparison?readCustomSection(comparison.content).body:'',comparison?.version??null);setComparison(undefined)}}>Χρήση αποθηκευμένου με αντίγραφο ανάκτησης</button></div>}</div>;
}
export function CustomVisitSectionsRead({bundle,sessionId}:{bundle:PatientBundle;sessionId:string}){return <>{bundle.sections.filter(s=>s.session_id===sessionId&&isCustomSection(s.section_key)).map(s=>{const value=readCustomSection(s.content);return <section className="visit-part" key={s.id}><header><h3><PatientVisualIcon name="notes"/>{value.title}</h3></header><p className={styles.read}>{value.body||'Δεν έχει καταγραφεί κείμενο.'}</p></section>})}</>}

