function cell(row:PatientRegistryRow,id:RegistryColumnId){
 switch(id){
  case 'registry':return String(row.registry_number).padStart(3,'0');
  case 'age':return row.reported_age==null?'—':row.reported_age+' ετών';
  case 'phone':return row.phone||'—';
