 useEffect(()=>{if(confirm)dialog.current?.showModal();else dialog.current?.close()},[confirm]);
 function persist(next=workspace){try{localStorage.setItem(storageKey,JSON.stringify(next));saved.current=JSON.stringify(next);setWorkspace(next);setStatus('Αποθηκεύτηκε μόνο σε αυτόν τον browser');setError('');return true}catch{setError('Δεν αποθηκεύτηκε στον browser. Το κείμενό σας παραμένει ανοιχτό· ελευθερώστε χώρο και δοκιμάστε ξανά.');return false}}
 function edit<K extends keyof Practice>(key:K,value:Practice[K]){setWorkspace(w=>({...w,draft:{...w.draft,[key]:value}}));setStatus('Μη αποθηκευμένες αλλαγές')}
 function closeDialog(){setConfirm(null);publishButton.current?.focus()}
 async function apply(){if(publishing)return;setPublishing(true);try{if(hosted&&confirm==='publish'){const response=await fetch('/api/presence',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({workspace,revision:publication?.revision||0})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Δεν δημοσιεύτηκε η σελίδα.');setPublication({slug:data.slug,revision:data.revision});if(persist(publish(workspace)))setStatus('Η δημόσια δοκιμαστική σελίδα ενημερώθηκε.');closeDialog();return;}const next=confirm==='publish'?publish(workspace):{...workspace,draft:clone(workspace.published!)};if(persist(next)){setStatus(confirm==='publish'?'Η δοκιμαστική σελίδα ενημερώθηκε. Δεν δημοσιεύτηκε στο διαδίκτυο.':'Επαναφέρθηκε η τελευταία δοκιμαστική δημοσίευση.');closeDialog()}}catch(e){setError(e instanceof Error?e.message:'Δεν ολοκληρώθηκε η ενέργεια.');closeDialog()}finally{setPublishing(false)}}
