 function renderFields(id:SectionId):ReactNode{
 if(id==='intro')return <><div className={styles.photoRow}><div className={styles.avatar} style={workspace.draft.photo?{backgroundImage:'url('+workspace.draft.photo+')'}:{}}>{workspace.draft.photo?'':initials(workspace.draft.name)}</div><label className={styles.upload}><Upload size={14}/>Αλλαγή φωτογραφίας<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>void photo(e.target.files?.[0])}/></label>{workspace.draft.photo&&<button type="button" className="small-button" onClick={()=>edit('photo','')}>Αφαίρεση φωτογραφίας</button>}</div><Field label="Ονοματεπώνυμο" value={workspace.draft.name} onChange={v=>edit('name',v)} max={100}/><Field label="Ειδικότητα" value={workspace.draft.specialty} onChange={v=>edit('specialty',v)} max={150}/><Field label="Καλωσόρισμα" value={workspace.draft.welcome} onChange={v=>edit('welcome',v)} multiline max={600}/></>;
 if(id==='services')return <>{workspace.draft.serviceItems.map((x,i)=><div key={i} className={styles.contentItem}><Field label={'Υπηρεσία '+(i+1)} value={x.title} onChange={title=>services(workspace.draft.serviceItems.map((item,n)=>n===i?{...item,title}:item))}/><Field label={'Περιγραφή υπηρεσίας '+(i+1)} value={x.description} multiline onChange={description=>services(workspace.draft.serviceItems.map((item,n)=>n===i?{...item,description}:item))}/><button className="small-button" type="button" onClick={()=>services(workspace.draft.serviceItems.filter((_,n)=>n!==i))}>Αφαίρεση υπηρεσίας {i+1}</button></div>)}<button className="small-button" type="button" disabled={workspace.draft.serviceItems.length>=30} onClick={()=>services([...workspace.draft.serviceItems,{title:'',description:''}])}>Προσθήκη υπηρεσίας</button><label className={styles.check}><input type="checkbox" checked={workspace.draft.online} onChange={e=>edit('online',e.target.checked)}/>Προσφέρω και online συνεδρίες</label></>;
 if(id==='faq')return <>{workspace.draft.faqItems.map((x,i)=><div key={i} className={styles.contentItem}><Field label={'Ερώτηση '+(i+1)} value={x.question} onChange={question=>faqs(workspace.draft.faqItems.map((item,n)=>n===i?{...item,question}:item))}/><Field label={'Απάντηση '+(i+1)} value={x.answer} multiline onChange={answer=>faqs(workspace.draft.faqItems.map((item,n)=>n===i?{...item,answer}:item))}/><button className="small-button" type="button" onClick={()=>faqs(workspace.draft.faqItems.filter((_,n)=>n!==i))}>Αφαίρεση ερώτησης {i+1}</button></div>)}<button className="small-button" type="button" disabled={workspace.draft.faqItems.length>=30} onClick={()=>faqs([...workspace.draft.faqItems,{question:'',answer:''}])}>Προσθήκη ερώτησης</button></>;
 if(id==='office')return <><Field label="Πόλη / περιοχή" value={workspace.draft.city} onChange={v=>edit('city',v)} max={120}/><Field label="Διεύθυνση & πρόσβαση" value={workspace.draft.office} onChange={v=>edit('office',v)} multiline/><p className={styles.help}>Προσθέστε διεύθυνση, συγκοινωνίες και στοιχεία προσβασιμότητας.</p></>;
 if(id==='contact')return <><Field label="Τηλέφωνο ιατρείου" value={workspace.draft.phone} onChange={v=>edit('phone',v)} max={40}/><Field label="Email ιατρείου" value={workspace.draft.email} onChange={v=>edit('email',v)} max={150}/><Field label="Ωράριο" value={workspace.draft.hours} onChange={v=>edit('hours',v)} max={200}/><p className={styles.help}>Τα αιτήματα παραμένουν σε αναμονή μέχρι την επιβεβαίωση. Στο preview δοκιμάζονται σε ξεχωριστό συνθετικό πρόγραμμα.</p></>;
 return <Field label="Βιογραφικό · σπουδές & εμπειρία" value={workspace.draft.bio} onChange={v=>edit('bio',v)} multiline/>
 }
 return <main className={'app-shell secondary-shell '+styles.shell}><aside className="sidebar"><div className="brand"><Link href="/" className="brand-mark">Ψ</Link><div className="brand-copy"><div className="brand-sub">Για μια οργανωμένη κλινική πράξη</div></div></div><nav className="nav" aria-label="Κύρια πλοήγηση">{nav.map(([Icon,label,href])=><Link key={href} className={'nav-item'+(href==='/digital-presence'?' active':'')} href={href}><Icon size={19}/><span>{label}</span></Link>)}</nav></aside><div className="workspace"><div className={styles.content}><Link className={styles.mobileBack} href="/"><ArrowLeft size={14}/>Επισκόπηση</Link><header className={styles.header}><div><p className={styles.eyebrow}>Ψηφιακή παρουσία</p><h1>{view==='google'?'Google & Maps':view==='articles'?'Άρθρα & ενημέρωση':view==='preview'?'Προεπισκόπηση προσχεδίου':'Η σελίδα του ιατρείου μου'}</h1><p>{view==='google'?'Επιλέξτε αν και πώς θα συνδέσετε το επαγγελματικό σας προφίλ.':view==='articles'?'Γράψτε, ελέγξτε και δημοσιεύστε κάθε άρθρο χωριστά.':'Επεξεργαστείτε τις ενότητες και δείτε πώς θα εμφανίζονται.'}</p></div><div className={styles.actions}>{view!=='google'&&<><button type="button" className="small-button" disabled={!ready} onClick={()=>{navigate('preview');setSent(false)}}><Eye size={15}/>Προεπισκόπηση προσχεδίου</button>{view!=='articles'&&<button title={hosted?"Δημοσίευση σελίδας και των ήδη δημοσιευμένων άρθρων":"Δημοσίευση μόνο της σελίδας — τα άρθρα δημοσιεύονται χωριστά"} ref={publishButton} type="button" className="record compact" disabled={!ready||!remoteReady||publishing} onClick={()=>setConfirm('publish')}>{hosted?'Δημοσίευση σελίδας':'Δημοσίευση σελίδας (δοκιμή)'}</button>}</>}</div></header><p className={styles.environmentNote}>{hosted?'Απομονωμένο preview · Το προσχέδιο αποθηκεύεται στον browser. Η δημοσίευση δημιουργεί δημόσια δοκιμαστική σελίδα. Μόνο συνθετικά στοιχεία.':'Συνθετικό preview · Αποθήκευση μόνο στον browser, χωρίς δημόσια δημοσίευση ή αποστολές.'}</p>{hosted&&publication&&<p className={styles.notice}>Δημόσιος σύνδεσμος: <a href={'/iatreio/'+publication.slug} target="_blank" rel="noreferrer">Άνοιγμα σελίδας ιατρείου</a> · <button type="button" className="small-button" onClick={()=>{void navigator.clipboard.writeText(window.location.origin+'/iatreio/'+publication.slug).then(()=>setStatus('Ο δημόσιος σύνδεσμος αντιγράφηκε.')).catch(()=>setError('Δεν αντιγράφηκε ο σύνδεσμος. Ανοίξτε τη δημόσια σελίδα και αντιγράψτε τη διεύθυνση.'))}}>Αντιγραφή link</button></p>}{error&&<div role="alert" className={styles.error}>{error}</div>}{view!=='google'&&<div className={styles.savebar}><span className={styles.publicationState}>{hosted?(publication?'Σελίδα: δημόσια στο preview':'Σελίδα: αδημοσίευτη'):workspace.published?'Σελίδα: δοκιμαστικά δημοσιευμένη':'Σελίδα: προσχέδιο'}</span><span role="status">{dirty?'Μη αποθηκευμένες αλλαγές':status||'Φόρτωση προσχεδίου…'}</span><button className="small-button" type="button" disabled={!ready||!dirty} onClick={()=>persist()}><Check size={14}/>Αποθήκευση προσχεδίου</button></div>}
 {!ready?<p>Το προσχέδιο δεν είναι διαθέσιμο ακόμη. Αν υπάρχει σφάλμα αποθήκευσης, δεν θα αντικατασταθεί.</p>:<><nav className={styles.tabs} aria-label="Προβολές ψηφιακής παρουσίας"><button aria-pressed={view==='editor'} onClick={()=>navigate('editor')} ><LayoutPanelTop size={15}/>Σελίδα ιατρείου</button><button aria-pressed={view==='articles'} onClick={()=>navigate('articles')}><FileText size={15}/>Άρθρα ({workspace.articles.length})</button><button aria-pressed={view==='public'} onClick={()=>navigate('public')}><Eye size={15}/>Δημοσιευμένη σελίδα</button><button aria-pressed={view==='requests'} onClick={()=>navigate('requests')}><Inbox size={15}/>{hosted?'Αιτήματα':'Αιτήματα ('+workspace.requests.length+')'}</button>{googleMaps&&<button aria-pressed={view==='google'} onClick={()=>navigate('google')}><Globe size={15}/>Google &amp; Maps</button>}</nav>
 {view==='google'&&googleMaps?<GoogleMaps practice={workspace.draft}/>:view==='editor'?<div className={styles.split}><section className={styles.editor} aria-label="Ενότητες σελίδας"><div className={styles.panelHead}><h2>Περιεχόμενο σελίδας</h2><p>Ανοίξτε μία ενότητα για να την επεξεργαστείτε.</p></div>{workspace.draft.order.map((id,index)=><div key={id} className={section===id?styles.sectionActive:styles.section}><div className={styles.sectionHead}><button className={styles.sectionTitle} aria-expanded={section===id} aria-controls={'fields-'+id} onClick={()=>setSection(id)}><span>{index+1}. {titles[id]}</span><small>{hints[id]}</small></button><div className={styles.order}><button title="Ορατότητα" aria-label={'Εμφάνιση '+titles[id]} aria-pressed={workspace.draft.visible[id]} disabled={id==='intro'||id==='contact'} onClick={()=>setWorkspace(w=>({...w,draft:toggle(w.draft,id)}))}>{workspace.draft.visible[id]?<Eye size={15}/>:<EyeOff size={15}/>}</button><button aria-label={'Πάνω '+titles[id]} disabled={index===0} onClick={()=>setWorkspace(w=>({...w,draft:move(w.draft,id,-1)}))}><ChevronUp size={15}/></button><button aria-label={'Κάτω '+titles[id]} disabled={index===5} onClick={()=>setWorkspace(w=>({...w,draft:move(w.draft,id,1)}))}><ChevronDown size={15}/></button></div></div>{section===id&&<div id={'fields-'+id} className={styles.fields}>{renderFields(id)}</div>}</div>)}<button type="button" className={styles.restore} disabled={!workspace.published} onClick={()=>setConfirm('restore')}><RotateCcw size={14}/>Επαναφορά σελίδας στην τελευταία δοκιμαστική δημοσίευση</button></section><section className={styles.preview} aria-label="Προεπισκόπηση ασθενή"><div className={styles.previewBar}><strong><Eye size={14}/>Προεπισκόπηση ασθενή</strong><div><button aria-label="Desktop" aria-pressed={!mobile} onClick={()=>setMobile(false)}><Monitor size={16}/></button><button aria-label="Κινητό" aria-pressed={mobile} onClick={()=>setMobile(true)}><Smartphone size={16}/></button></div></div><p className={styles.url}>Προσχέδιο · Ενδεικτικός σύνδεσμος: noima.example/iatreio/anna-deigma</p><div className={mobile?styles.mobilePreview:styles.desktopPreview}><PracticePage articles={workspace.articles} practice={workspace.draft} selected={section} onRequest={hosted?undefined:()=>{navigate('public');setRequestOpen(true);setSent(false)}}/></div></section></div> :view==='articles'?<div className={styles.split}><ArticleEditor articles={workspace.articles} onChange={articles=>setWorkspace(w=>({...w,articles}))} onSave={articles=>persist({...workspace,articles})} onPreview={content=>{setArticlePreview(content.id);requestAnimationFrame(()=>{articlePreviewPanel.current?.focus();articlePreviewPanel.current?.scrollIntoView({block:'nearest'})})}}/><section ref={articlePreviewPanel} tabIndex={-1} className={styles.articlePreviewPanel} aria-label="Προεπισκόπηση προσχεδίου άρθρου">{articlePreview?<><p className={styles.notice}>Τρέχον προσχέδιο · Η δημοσιευμένη έκδοση δεν αλλάζει.</p><ArticleReader content={workspace.articles.find(a=>a.id===articlePreview)!.draft} onBack={()=>setArticlePreview(null)}/></>:<><Eye size={24}/><h2>Δείτε το άρθρο πριν το δημοσιεύσετε</h2><p>Επιλέξτε «Προεπισκόπηση άρθρου» στον editor. Η σελίδα ασθενή δείχνει μόνο τη δοκιμαστικά δημοσιευμένη έκδοση.</p><p className={styles.help}>{workspace.articles.filter(a=>a.published).length} δοκιμαστικά δημοσιευμένα · {workspace.articles.filter(a=>!a.published).length} προσχέδια</p></>}</section></div>:(view==='public'&&hosted)?<section className={styles.publicView}><h2>Δημοσιευμένη σελίδα</h2><p>{publication?'Η δημοσιευμένη έκδοση ανοίγει στον δημόσιο σύνδεσμο. Οι αλλαγές του προσχεδίου εμφανίζονται μόνο μετά από νέα δημοσίευση.':'Δεν υπάρχει ακόμη δημόσια δημοσίευση.'}</p>{publication&&<a className="small-button" href={'/iatreio/'+publication.slug} target="_blank" rel="noreferrer">Άνοιγμα δημοσιευμένης σελίδας</a>}</section>:(view==='public'||view==='preview')?<section className={styles.publicView}><button className="small-button" onClick={()=>navigate('editor')}><ArrowLeft size={15}/>Πίσω στον editor</button><p className={styles.notice}>{view==='preview'?'Τρέχον προσχέδιο — οι αλλαγές δεν έχουν δημοσιευτεί.':workspace.published?'Τελευταία δοκιμαστική δημοσίευση — το προσχέδιο δεν την αλλάζει.':'Δεν υπάρχει ακόμη δοκιμαστική δημοσίευση. Επιστρέψτε στον editor για να δημοσιεύσετε τη σελίδα.'}</p><PracticePage articles={workspace.articles} practice={view==='preview'?workspace.draft:workspace.published||workspace.draft} onRequest={!hosted&&view==='public'&&workspace.published?()=>{setRequestOpen(true);setSent(false)}:undefined}/>{sent&&<div role="status" className={styles.notice}>Το συνθετικό αίτημα καταγράφηκε. Αναμένεται επιβεβαίωση — δεν δημιουργήθηκε πραγματικό ραντεβού ή φάκελος.</div>}{view==='public'&&requestOpen&&workspace.published&&<form className={styles.requestForm} onSubmit={e=>{e.preventDefault();submitRequest()}}><h2>Συνθετικό αίτημα ραντεβού</h2><p>Χρησιμοποιήστε μόνο υποθετικά στοιχεία. Δεν αποστέλλεται email.</p><Field label="Ονοματεπώνυμο αιτούντος" value={request.name} onChange={name=>setRequest(r=>({...r,name}))}/><Field label="Email αιτούντος" value={request.email} onChange={email=>setRequest(r=>({...r,email}))}/><Field label="Τηλέφωνο αιτούντος" value={request.phone} onChange={phone=>setRequest(r=>({...r,phone}))}/><label className={styles.field}>Είδος συνεδρίας<select value={request.kind} onChange={e=>setRequest(r=>({...r,kind:e.target.value}))}><option>Δια ζώσης</option>{workspace.published.online&&<option>Online</option>}</select></label><Field label="Προτιμώμενη ημέρα & ώρα" value={request.preference} onChange={preference=>setRequest(r=>({...r,preference}))}/><p>Το αίτημα δεν αποτελεί επιβεβαιωμένο ραντεβού.</p><div className={styles.actions}><button type="button" className="small-button" onClick={()=>setRequestOpen(false)}>Ακύρωση</button><button className="record compact" type="submit">Υποβολή συνθετικού αιτήματος</button></div></form>}</section>:hosted?<HostedRequests/>:<section className={styles.requests}><h2>Αιτήματα ραντεβού</h2><p>Προσομοίωση ημερολογίου · Δεν συνδέεται ακόμη με το πραγματικό πρόγραμμα ή φακέλους.</p>{!workspace.requests.length?<p>Δεν υπάρχουν αιτήματα. Δοκιμάστε πρώτα τη σελίδα ασθενή.</p>:workspace.requests.map(r=><article key={r.id}><h3>{r.name}</h3><p>{r.kind} · Προτίμηση: {r.preference}</p><p>{r.email} · {r.phone}</p><strong>{r.status==='pending'?'Αναμονή επιβεβαίωσης':'Επιβεβαιωμένο στο συνθετικό πρόγραμμα'}</strong>{r.status==='pending'?<form onSubmit={e=>{e.preventDefault();try{persist(confirmRequest(workspace,r.id,slot))}catch(e){setError((e as Error).message)}}}><label className={styles.field}>Ώρα στο συνθετικό πρόγραμμα<input type="datetime-local" required value={slot} onChange={e=>setSlot(e.target.value)}/></label><p className={styles.help}>Στην πραγματική σύνδεση θα προηγείται έλεγχος υπάρχοντος ασθενή. Το παράδειγμα δεν δημιουργεί φάκελο.</p><button type="submit" className="small-button">Επιβεβαίωση στο παράδειγμα</button></form>:<p>{r.slot.replace('T',' · ')}</p>}</article>)}</section>}</>}
 <dialog ref={dialog} onCancel={()=>closeDialog()} className={styles.dialog}><h2>{confirm==='publish'?(hosted?'Δημοσίευση δημόσιας δοκιμαστικής σελίδας;':'Δοκιμαστική δημοσίευση;'):'Επαναφορά προσχεδίου;'}</h2><p>{confirm==='publish'?hosted?'Το περιεχόμενο και τα δημοσιευμένα άρθρα θα είναι προσβάσιμα σε όποιον έχει το link, χωρίς σύνδεση. Χρησιμοποιήστε μόνο συνθετικό περιεχόμενο.':'Θα ενημερωθεί μόνο η συνθετική σελίδα αυτού του browser. Δεν θα δημοσιευτεί στο διαδίκτυο.':'Το προσχέδιο θα αντικατασταθεί από την τελευταία δοκιμαστική δημοσίευση.'}</p><div className={styles.actions}><button className="small-button" onClick={closeDialog}>Ακύρωση</button><button className="record compact" disabled={publishing} onClick={()=>void apply()}>{publishing?'Δημοσίευση…':'Επιβεβαίωση'}</button></div></dialog></div></div></main>
